WHERE ID = :ID;

-- SHOP.CUSTOMERS: MERGE
MERGE INTO SHOP.CUSTOMERS t
USING (SELECT :ID AS ID, :NAME AS NAME, :EMAIL AS EMAIL, :COUNTRY_ID AS COUNTRY_ID FROM DUAL) s
ON (t.ID = s.ID)
WHEN MATCHED THEN
